:root {
  --bg-card: #1a1a1a;
  --bg-header: #111111;
  --bg-map: #2a2010;
  --bg-panel: #222222;
  --bg-side: #1e1e1e;
  --color-fire-a: #ff4500;
  --color-fire-b: #ff8c00;
  --color-perimeter: #ffcc00;
  --color-critical: #ff2d2d;
  --color-title: #ffffff;
  --color-muted: #999999;
  --color-accent: #ff6a00;
  --color-bar-bg: #333333;
  --color-bar-fill: #ff6a00;
  --color-chip-bg: #2e2e2e;
  --color-chip-val: #ffcc00;
  --color-danger: #ff4500;
  --color-cond-bg: #2a2a2a;
  --color-evac-red: #ff2d2d;
  --color-evac-red-bg: #3a0a0a;
  --color-evac-orange: #ff8c00;
  --color-evac-orange-bg: #3a2000;
  --color-evac-yellow: #ffcc00;
  --color-evac-yellow-bg: #2e2a00;
  --color-dot-active: #00e676;
  --color-map-label: #ffcc00;
  --color-map-grid: #3a3010;
  --color-panel-title: #ff8c00;
}

.dashboard {
  background: var(--bg-card);
  border-radius: 10px;
  width: 500px;
  max-width: 500px;
  overflow: hidden;
  border: 1px solid var(--color-accent);
}

.dash-header {
  background: var(--bg-header);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  border-bottom: 2px solid var(--color-accent);
}

.header-left {
  display: flex;
  align-items: center;
  gap: 8px;
}

.status-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--color-dot-active);
  border: 2px solid var(--bg-header);
  outline: 2px solid var(--color-dot-active);
}

.dash-title {
  font-size: 14px;
  font-weight: 800;
  color: var(--color-title);
  letter-spacing: 2px;
  margin: 0;
}

.incident-id {
  font-size: 11px;
  color: var(--color-muted);
  background: var(--bg-panel);
  padding: 2px 7px;
  border-radius: 4px;
  font-weight: 600;
  letter-spacing: 1px;
}

.header-right {
  display: flex;
  align-items: center;
  gap: 7px;
}

.threat-label {
  font-size: 10px;
  font-weight: 700;
  color: var(--color-muted);
  letter-spacing: 1px;
}

.threat-badge {
  font-size: 11px;
  font-weight: 800;
  color: var(--color-critical);
  background: var(--color-evac-red-bg);
  border: 1px solid var(--color-critical);
  padding: 3px 9px;
  border-radius: 4px;
  letter-spacing: 1.5px;
}

.dash-body {
  display: flex;
  gap: 0;
}

.map-panel {
  flex: 1 1 auto;
  padding: 12px;
  border-right: 1px solid #333;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.map-placeholder {
  background: var(--bg-map);
  border-radius: 7px;
  height: 140px;
  position: relative;
  overflow: hidden;
  border: 1px solid #3a3010;
}

.map-grid {
  position: absolute;
  inset: 0;
  background-size: 20px 20px;
  background-color: var(--bg-map);
  border-image: none;
  opacity: 0.4;
}

.fire-zone {
  position: absolute;
  border-radius: 50%;
}

.zone-a {
  width: 64px;
  height: 52px;
  background: var(--color-fire-a);
  opacity: 0.75;
  top: 36px;
  left: 52px;
  border-radius: 40% 60% 55% 45%;
}

.zone-b {
  width: 42px;
  height: 34px;
  background: var(--color-fire-b);
  opacity: 0.65;
  top: 52px;
  left: 90px;
  border-radius: 50% 40% 60% 50%;
}

.perimeter-ring {
  position: absolute;
  width: 96px;
  height: 80px;
  top: 26px;
  left: 36px;
  border: 2px dashed var(--color-perimeter);
  border-radius: 45% 55% 50% 50%;
  opacity: 0.6;
}

.map-label {
  position: absolute;
  bottom: 7px;
  left: 0;
  right: 0;
  text-align: center;
  font-size: 10px;
  font-weight: 700;
  color: var(--color-map-label);
  letter-spacing: 1.5px;
}

.map-stats {
  display: flex;
  gap: 8px;
}

.stat-chip {
  flex: 1;
  background: var(--color-chip-bg);
  border-radius: 6px;
  padding: 7px 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  border: 1px solid #333;
}

.chip-val {
  font-size: 18px;
  font-weight: 800;
  color: var(--color-chip-val);
  line-height: 1;
}

.chip-unit {
  font-size: 10px;
  color: var(--color-muted);
  font-weight: 600;
  margin-top: 2px;
}

.side-panels {
  width: 185px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.resources-panel {
  padding: 10px 12px;
  border-bottom: 1px solid #333;
}

.panel-title {
  font-size: 10px;
  font-weight: 800;
  color: var(--color-panel-title);
  letter-spacing: 1.5px;
  text-transform: uppercase;
  margin: 0 0 7px 0;
}

.resource-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.resource-item {
  display: grid;
  grid-template-columns: 16px 1fr auto 60px;
  align-items: center;
  gap: 5px;
}

.res-icon {
  font-size: 12px;
  line-height: 1;
}

.res-name {
  font-size: 11px;
  color: var(--color-muted);
  font-weight: 500;
  white-space: nowrap;
}

.res-count {
  font-size: 11px;
  font-weight: 700;
  color: var(--color-title);
}

.res-bar-wrap {
  height: 5px;
  background: var(--color-bar-bg);
  border-radius: 3px;
  overflow: hidden;
}

.res-bar {
  display: block;
  height: 100%;
  width: var(--fill);
  background: var(--color-bar-fill);
  border-radius: 3px;
}

.conditions-panel {
  padding: 10px 12px;
}

.conditions-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 5px;
}

.cond-cell {
  background: var(--color-cond-bg);
  border-radius: 5px;
  padding: 6px 7px;
  display: flex;
  flex-direction: column;
  align-items: center;
  border: 1px solid #333;
}

.cond-danger {
  border-color: var(--color-danger);
  background: var(--color-evac-red-bg);
}

.cond-val {
  font-size: 13px;
  font-weight: 800;
  color: var(--color-title);
  line-height: 1;
}

.cond-lbl {
  font-size: 9px;
  color: var(--color-muted);
  font-weight: 600;
  margin-top: 2px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.dash-footer {
  background: var(--bg-header);
  border-top: 1px solid #333;
  padding: 8px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.updated {
  font-size: 10px;
  color: var(--color-muted);
  font-weight: 500;
}

.evac-zones {
  display: flex;
  gap: 5px;
}

.evac-tag {
  font-size: 9px;
  font-weight: 800;
  padding: 3px 7px;
  border-radius: 4px;
  letter-spacing: 0.5px;
}

.evac-red {
  color: var(--color-evac-red);
  background: var(--color-evac-red-bg);
  border: 1px solid var(--color-evac-red);
}

.evac-orange {
  color: var(--color-evac-orange);
  background: var(--color-evac-orange-bg);
  border: 1px solid var(--color-evac-orange);
}

.evac-yellow {
  color: var(--color-evac-yellow);
  background: var(--color-evac-yellow-bg);
  border: 1px solid var(--color-evac-yellow);
}
